using System.IO;using System.IO.Pipes;using System.Text.Json;namespace Luma;public sealed class SingleInstanceHost:IDisposable{readonly string name;readonly Mutex mutex;readonly CancellationTokenSource cts=new();public bool IsPrimary{get;}public event Action<string[]>? CommandReceived;public SingleInstanceHost(string n){name=n;mutex=new(true,n,out var c);IsPrimary=c;}public void StartListening(){if(!IsPrimary)return;_=Task.Run(async()=>{while(!cts.IsCancellationRequested)try{using var s=new NamedPipeServerStream(name,PipeDirection.In,1,PipeTransmissionMode.Byte,PipeOptions.Asynchronous);await s.WaitForConnectionAsync(cts.Token);using var r=new StreamReader(s);CommandReceived?.Invoke(JsonSerializer.Deserialize<string[]>(await r.ReadToEndAsync(cts.Token))??[]);}catch(OperationCanceledException){break;}catch{await Task.Delay(200);}});}public void Send(string[] a){try{using var c=new NamedPipeClientStream(".",name,PipeDirection.Out);c.Connect(1500);using var w=new StreamWriter(c){AutoFlush=true};w.Write(JsonSerializer.Serialize(a));}catch{}}public void Dispose(){cts.Cancel();if(IsPrimary)mutex.ReleaseMutex();mutex.Dispose();cts.Dispose();}}